=== FILE: rtl/axi4_lite_regs.v ===
`timescale 1ns/1ps
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md (holding registers,
// READY from state only, 1-cycle response latency, SLVERR for unmapped).
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output reg  [1:0]              s_axil_bresp,
    output reg                     s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output reg  [DATA_WIDTH-1:0]   s_axil_rdata,
    output reg  [1:0]              s_axil_rresp,
    output reg                     s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // Write-side state: held flags (reset) and holding registers (datapath).
  reg                  aw_held;
  reg                  w_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;

  // Register file: four separate registers.
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  // READY is a function of state only.
  assign s_axil_awready = !aw_held && !s_axil_bvalid;
  assign s_axil_wready  = !w_held  && !s_axil_bvalid;
  assign s_axil_arready = !s_axil_rvalid;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid  && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;

  // The write fires on the edge that completes the AW/W pair.
  wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];

  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  // Old value of the register being written.
  reg [DATA_WIDTH-1:0] wr_old;
  always @* begin
    wr_old = {DATA_WIDTH{1'b0}};
    case (wr_idx)
      2'd0:    wr_old = reg0;
      2'd1:    wr_old = reg1;
      2'd2:    wr_old = reg2;
      2'd3:    wr_old = reg3;
      default: wr_old = {DATA_WIDTH{1'b0}};
    endcase
  end

  // Register selected by the read address.
  reg [DATA_WIDTH-1:0] rd_sel;
  always @* begin
    rd_sel = {DATA_WIDTH{1'b0}};
    case (rd_idx)
      2'd0:    rd_sel = reg0;
      2'd1:    rd_sel = reg1;
      2'd2:    rd_sel = reg2;
      2'd3:    rd_sel = reg3;
      default: rd_sel = {DATA_WIDTH{1'b0}};
    endcase
  end

  // Byte mask from the strobes: bit n enables bits 8n+7:8n.
  wire [DATA_WIDTH-1:0] wr_mask;
  genvar gi;
  generate
    for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wr_mask
      assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
    end
  endgenerate

  wire [DATA_WIDTH-1:0] wr_merged = (wr_old & ~wr_mask) | (wr_data & wr_mask);

  // Register file update.
  always @(posedge aclk) begin
    if (!aresetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else if (do_write && wr_mapped) begin
      case (wr_idx)
        2'd0:    reg0 <= wr_merged;
        2'd1:    reg1 <= wr_merged;
        2'd2:    reg2 <= wr_merged;
        2'd3:    reg3 <= wr_merged;
        default: ;
      endcase
    end
  end

  // Write control: held flags and the B channel.
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held       <= 1'b0;
      w_held        <= 1'b0;
      s_axil_bvalid <= 1'b0;
      s_axil_bresp  <= RESP_OKAY;
    end else if (do_write) begin
      aw_held       <= 1'b0;
      w_held        <= 1'b0;
      s_axil_bvalid <= 1'b1;
      s_axil_bresp  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
    end else begin
      if (aw_hs) begin
        aw_held <= 1'b1;
      end
      if (w_hs) begin
        w_held <= 1'b1;
      end
      if (s_axil_bvalid && s_axil_bready) begin
        s_axil_bvalid <= 1'b0;
      end
    end
  end

  // Holding registers (datapath, not reset; validity is in the held flags).
  always @(posedge aclk) begin
    if (aw_hs) begin
      aw_addr_q <= s_axil_awaddr;
    end
    if (w_hs) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

  // Read channel.
  always @(posedge aclk) begin
    if (!aresetn) begin
      s_axil_rvalid <= 1'b0;
      s_axil_rresp  <= RESP_OKAY;
      s_axil_rdata  <= {DATA_WIDTH{1'b0}};
    end else if (ar_hs) begin
      s_axil_rvalid <= 1'b1;
      s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
      s_axil_rdata  <= rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
    end else if (s_axil_rvalid && s_axil_rready) begin
      s_axil_rvalid <= 1'b0;
    end
  end

`ifdef FORMAL
  // Design-intent assertions (not part of this submission's proof).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!aresetn);
  end

  always @(posedge aclk) begin
    if (f_past_valid && !$past(aresetn)) begin
      assert(!s_axil_bvalid);
      assert(!s_axil_rvalid);
      assert(!aw_held);
      assert(!w_held);
    end
    if (f_past_valid && $past(aresetn) && $past(s_axil_bvalid && !s_axil_bready)) begin
      assert(s_axil_bvalid);
      assert(s_axil_bresp == $past(s_axil_bresp));
    end
    if (f_past_valid && $past(aresetn) && $past(s_axil_rvalid && !s_axil_rready)) begin
      assert(s_axil_rvalid);
      assert(s_axil_rresp == $past(s_axil_rresp));
      assert(s_axil_rdata == $past(s_axil_rdata));
    end
  end

  always @(*) begin
    if (f_past_valid) begin
      assert(s_axil_bresp != 2'b01);
      assert(s_axil_rresp != 2'b01);
      if (s_axil_bvalid) assert(!aw_held && !w_held);
    end
  end

  always @(*) begin
    cover(f_past_valid && s_axil_bvalid && s_axil_rvalid);
  end
`endif

endmodule
=== END FILE ===
