`timescale 1ns/1ps
// Self-checking testbench for axi4_lite_regs.
// Inputs are driven 1 ns after the falling edge; READY/VALID are sampled at
// the same point, before the next rising edge, so there is no race.
module axi4_lite_regs_tb;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  integer        passed;
  integer        failed;
  integer        k;
  reg [3:0]      baddr;
  reg [31:0]     bdata;
  reg [31:0]     model [0:3];
  reg [8*64-1:0] nonce;

  axi4_lite_regs #(
    .ADDR_WIDTH(4),
    .DATA_WIDTH(32)
  ) dut (
    .aclk          (aclk),
    .aresetn       (aresetn),
    .s_axil_awaddr (awaddr),
    .s_axil_awvalid(awvalid),
    .s_axil_awready(awready),
    .s_axil_wdata  (wdata),
    .s_axil_wstrb  (wstrb),
    .s_axil_wvalid (wvalid),
    .s_axil_wready (wready),
    .s_axil_bresp  (bresp),
    .s_axil_bvalid (bvalid),
    .s_axil_bready (bready),
    .s_axil_araddr (araddr),
    .s_axil_arvalid(arvalid),
    .s_axil_arready(arready),
    .s_axil_rdata  (rdata),
    .s_axil_rresp  (rresp),
    .s_axil_rvalid (rvalid),
    .s_axil_rready (rready)
  );

  initial aclk = 1'b0;
  always #5 aclk = ~aclk;

  // ---------------------------------------------------------------- checks
  task check(input ok, input integer id);
    begin
      if (ok) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t", id, $time);
      end
    end
  endtask

  task check_eq(input [31:0] got, input [31:0] exp, input integer id);
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %h expected %h", id, $time, got, exp);
      end
    end
  endtask

  function [31:0] merge(input [31:0] old, input [31:0] d, input [3:0] s);
    integer b;
    begin
      merge = old;
      for (b = 0; b < 4; b = b + 1) begin
        if (s[b]) merge[8*b +: 8] = d[8*b +: 8];
      end
    end
  endfunction

  // Advance to 1 ns after the next falling edge.
  task tick;
    begin
      @(negedge aclk);
      #1;
    end
  endtask

  // ------------------------------------------------------------ reset
  task do_reset;
    integer m;
    begin
      aresetn = 1'b0;
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      repeat (3) tick;
      aresetn = 1'b1;
      tick;
      for (m = 0; m < 4; m = m + 1) model[m] = 32'd0;
      check(!bvalid, 50);
      check(!rvalid, 51);
      check(awready && wready && arready, 52);
    end
  endtask

  // Drive the asserted AW and/or W until each is accepted.
  task run_wchan;
    integer n;
    reg aw_fire;
    reg w_fire;
    begin
      n = 0;
      while ((awvalid || wvalid) && n < 20) begin
        check(!bvalid, 1);              // no B before both halves accepted
        aw_fire = awvalid && awready;
        w_fire  = wvalid && wready;
        tick;
        if (aw_fire) awvalid = 1'b0;
        if (w_fire)  wvalid  = 1'b0;
        n = n + 1;
      end
      check(!awvalid && !wvalid, 2);     // accepted within the bound
      awvalid = 1'b0;
      wvalid  = 1'b0;
    end
  endtask

  task idle_nob(input integer cycles);
    integer n;
    begin
      n = 0;
      while (n < cycles) begin
        check(!bvalid, 90);
        tick;
        n = n + 1;
      end
    end
  endtask

  // mode 0: AW and W together; 1: AW first; 2: W first.
  task axi_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                 input integer mode, input integer bdelay);
    reg [1:0] exp_resp;
    reg [1:0] resp_hold;
    integer   lat;
    integer   n;
    begin
      exp_resp = (addr[1:0] == 2'b00) ? 2'b00 : 2'b10;
      bready   = (bdelay == 0) ? 1'b1 : 1'b0;
      awaddr   = addr;
      wdata    = data;
      wstrb    = strb;
      if (mode == 0) begin
        awvalid = 1'b1;
        wvalid  = 1'b1;
        run_wchan;
      end else if (mode == 1) begin
        awvalid = 1'b1;
        run_wchan;
        check(!awready && wready, 12);
        idle_nob(3);
        wvalid = 1'b1;
        run_wchan;
      end else begin
        wvalid = 1'b1;
        run_wchan;
        check(awready && !wready, 13);
        idle_nob(3);
        awvalid = 1'b1;
        run_wchan;
      end
      // Latency: cycles from the completing edge to BVALID high.
      lat = 1;
      while (!bvalid && lat < 4) begin
        tick;
        lat = lat + 1;
      end
      check(bvalid, 3);
      check(lat <= 2, 4);
      check_eq({30'd0, bresp}, {30'd0, exp_resp}, 5);
      check(!awready && !wready, 6);
      resp_hold = bresp;
      n = 0;
      while (n < bdelay) begin
        tick;
        check(bvalid, 7);
        check_eq({30'd0, bresp}, {30'd0, resp_hold}, 8);
        check(!awready && !wready, 9);
        n = n + 1;
      end
      bready = 1'b1;
      tick;
      check(!bvalid, 10);
      check(awready && wready, 11);      // next write can start at once
      if (exp_resp == 2'b00) begin
        model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
      end
    end
  endtask

  task axi_read(input [3:0] addr, input integer rdelay);
    reg [31:0] exp_data;
    reg [1:0]  exp_resp;
    reg        ar_fire;
    integer    n;
    integer    lat;
    begin
      if (addr[1:0] == 2'b00) begin
        exp_data = model[addr[3:2]];
        exp_resp = 2'b00;
      end else begin
        exp_data = 32'd0;
        exp_resp = 2'b10;
      end
      rready  = (rdelay == 0);
      araddr  = addr;
      arvalid = 1'b1;
      n = 0;
      while (arvalid && n < 20) begin
        check(!rvalid, 20);
        ar_fire = arvalid && arready;
        tick;
        if (ar_fire) arvalid = 1'b0;
        n = n + 1;
      end
      check(!arvalid, 21);
      arvalid = 1'b0;
      lat = 1;
      while (!rvalid && lat < 4) begin
        tick;
        lat = lat + 1;
      end
      check(rvalid, 22);
      check(lat <= 2, 23);
      check_eq(rdata, exp_data, 24);
      check_eq({30'd0, rresp}, {30'd0, exp_resp}, 25);
      check(!arready, 26);
      n = 0;
      while (n < rdelay) begin
        tick;
        check(rvalid, 27);
        check_eq(rdata, exp_data, 28);
        check_eq({30'd0, rresp}, {30'd0, exp_resp}, 29);
        check(!arready, 30);
        n = n + 1;
      end
      rready = 1'b1;
      tick;
      check(!rvalid, 31);
      check(arready, 32);                // next read can start at once
    end
  endtask

  // Write and read presented on the same clock (different registers).
  task rw_together(input [3:0] waddr, input [31:0] data, input [3:0] strb,
                   input [3:0] raddr);
    reg [31:0] exp_rdata;
    reg        got_b;
    reg        got_r;
    reg        aw_fire;
    reg        w_fire;
    reg        ar_fire;
    integer    n;
    integer    aw_cyc;
    integer    ar_cyc;
    begin
      exp_rdata = model[raddr[3:2]];
      bready  = 1'b1;
      rready  = 1'b1;
      awaddr  = waddr;
      wdata   = data;
      wstrb   = strb;
      araddr  = raddr;
      awvalid = 1'b1;
      wvalid  = 1'b1;
      arvalid = 1'b1;
      got_b   = 1'b0;
      got_r   = 1'b0;
      aw_cyc  = -1;
      ar_cyc  = -1;
      n = 0;
      while ((awvalid || wvalid || arvalid || !got_b || !got_r) && n < 20) begin
        if (bvalid) begin
          check(!got_b, 60);
          check_eq({30'd0, bresp}, 32'd0, 61);
          got_b = 1'b1;
        end
        if (rvalid) begin
          check(!got_r, 62);
          check_eq(rdata, exp_rdata, 63);
          check_eq({30'd0, rresp}, 32'd0, 64);
          got_r = 1'b1;
        end
        aw_fire = awvalid && awready;
        w_fire  = wvalid && wready;
        ar_fire = arvalid && arready;
        if (aw_fire) aw_cyc = n;
        if (ar_fire) ar_cyc = n;
        tick;
        if (aw_fire) awvalid = 1'b0;
        if (w_fire)  wvalid  = 1'b0;
        if (ar_fire) arvalid = 1'b0;
        n = n + 1;
      end
      check(got_b && got_r, 65);
      check(aw_cyc == ar_cyc, 66);
      check(!bvalid && !rvalid, 67);
      model[waddr[3:2]] = merge(model[waddr[3:2]], data, strb);
    end
  endtask

  task read_all;
    begin
      axi_read(4'h0, 0);
      axi_read(4'h4, 0);
      axi_read(4'h8, 0);
      axi_read(4'hC, 0);
    end
  endtask

  // ------------------------------------------------------------ sequence
  initial begin
    passed  = 0;
    failed  = 0;
    aresetn = 1'b0;
    awaddr  = 4'h0;
    awvalid = 1'b0;
    wdata   = 32'd0;
    wstrb   = 4'h0;
    wvalid  = 1'b0;
    bready  = 1'b1;
    araddr  = 4'h0;
    arvalid = 1'b0;
    rready  = 1'b1;
    for (k = 0; k < 4; k = k + 1) model[k] = 32'd0;

    tick;
    do_reset;

    // Reset values.
    read_all;

    // Write then read every register.
    axi_write(4'h0, 32'h11223344, 4'hF, 0, 0);
    axi_write(4'h4, 32'h55667788, 4'hF, 0, 0);
    axi_write(4'h8, 32'h99AABBCC, 4'hF, 0, 0);
    axi_write(4'hC, 32'hDDEEFF00, 4'hF, 0, 0);
    read_all;

    // Partial and empty strobes, in every arrival order.
    axi_write(4'h4, 32'hA5A5A5A5, 4'b0101, 0, 0);
    axi_write(4'h8, 32'hCAFEF00D, 4'b1000, 1, 0);
    axi_write(4'hC, 32'hFFFFFFFF, 4'b0000, 2, 0);
    axi_write(4'h0, 32'h0BADBEEF, 4'b0110, 2, 0);
    read_all;

    // AW before W and W before AW, full strobes.
    axi_write(4'h0, 32'h01234567, 4'hF, 1, 0);
    axi_write(4'hC, 32'h89ABCDEF, 4'hF, 2, 0);
    read_all;

    // B and R backpressure.
    axi_write(4'h8, 32'h13579BDF, 4'hF, 0, 5);
    axi_write(4'h4, 32'h2468ACE0, 4'b0011, 1, 3);
    axi_read(4'h8, 5);
    axi_read(4'h4, 4);

    // Back-to-back transactions.
    for (k = 0; k < 8; k = k + 1) begin
      baddr = {k[1:0], 2'b00};
      bdata = 32'hC0DE0000 | k;
      axi_write(baddr, bdata, 4'hF, 0, 0);
    end
    for (k = 0; k < 8; k = k + 1) begin
      baddr = {k[1:0], 2'b00};
      axi_read(baddr, 0);
    end

    // SLVERR policy: unmapped writes change nothing; unmapped reads return 0.
    axi_write(4'h5, 32'hFFFFFFFF, 4'hF, 0, 0);
    axi_write(4'hE, 32'hFFFFFFFF, 4'hF, 1, 0);
    axi_write(4'h3, 32'hFFFFFFFF, 4'hF, 2, 2);
    axi_read(4'h5, 0);
    axi_read(4'hE, 3);
    axi_read(4'h1, 0);
    read_all;

    // Read and write accepted on the same clock.
    rw_together(4'h0, 32'h5A5A5A5A, 4'hF, 4'h8);
    rw_together(4'hC, 32'h0F0F0F0F, 4'b1100, 4'h4);
    read_all;

    // Reset during traffic 1: a half-accepted write is discarded.
    bready  = 1'b1;
    awaddr  = 4'h4;
    awvalid = 1'b1;
    run_wchan;
    check(!awready && wready, 70);
    do_reset;
    wdata   = 32'hDEADBEEF;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    run_wchan;
    idle_nob(4);                         // AW was dropped: no write completes
    awaddr  = 4'h8;
    awvalid = 1'b1;
    run_wchan;
    check(bvalid, 71);
    check_eq({30'd0, bresp}, 32'd0, 72);
    tick;
    check(!bvalid, 73);
    model[2] = 32'hDEADBEEF;
    axi_read(4'h4, 0);
    axi_read(4'h8, 0);

    // Reset during traffic 2: pending B and R are dropped, registers clear.
    bready  = 1'b0;
    rready  = 1'b0;
    araddr  = 4'h8;
    arvalid = 1'b1;
    check(arready, 79);
    tick;
    arvalid = 1'b0;
    awaddr  = 4'h0;
    wdata   = 32'h12345678;
    wstrb   = 4'hF;
    awvalid = 1'b1;
    wvalid  = 1'b1;
    run_wchan;
    check(bvalid && rvalid, 80);
    tick;
    check(bvalid && rvalid, 81);
    do_reset;
    bready = 1'b1;
    rready = 1'b1;
    tick;
    check(!bvalid && !rvalid, 82);
    read_all;

    // Verdict.
    nonce = {64{8'h00}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
      $display("note: no nirmaan_nonce plusarg given");
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
